		gDetail -= line(P.x - fx, 0.0016) * step(0.3, N.z) * step(hip - 0.05, P.y) * step(P.y, wtop - 0.04) * 0.9;
		gDetail -= line(P.x, 0.0014) * step(0.3, N.z) * step(hip - 0.02, P.y) * step(P.y, wtop - 0.04) * 0.5;
